    // Validate the input JWT token's size against a reasonable maximum limit (e.g., 8KB)
    const size_t MAX_TOKEN_SIZE = 8192; // 8KB
    if (token.length() > MAX_TOKEN_SIZE) {
        return decoded_claims_json;
    }

    // Security Guideline: Key Strength Validation
    // Validate the cryptographic key for sufficient strength (minimum length of 32 bytes for HS256)
    const size_t MIN_HS256_KEY_LENGTH = 32; // 256 bits = 32 bytes
    if (key.length() < MIN_HS256_KEY_LENGTH) {
        return decoded_claims_json;
    }

    try {
