def _evaluate_ast_node(node):
    """
    Recursively evaluates a restricted AST node.
    Raises ValueError for unsupported nodes or operations.
    Raises ZeroDivisionError for division by zero.
    """
    if isinstance(node, ast.Expression):
        return _evaluate_ast_node(node.body)
    elif isinstance(node, ast.Constant): # For Python 3.8+
        if isinstance(node.value, (int, float)):
