        raise ValueError("Unsupported constant type.")
    elif isinstance(node, ast.Num): # For Python < 3.8 (deprecated in 3.8)
        return node.n
    elif isinstance(node, ast.BinOp):
        op_func = _OP_MAP.get(type(node.op))
        if op_func is None:
            raise ValueError("Unsupported binary operator.")
        left = _evaluate_ast_node(node.left)
        right = _evaluate_ast_node(node.right)
        if op_func == operator.truediv and right == 0:
